import { uuidv7 } from 'uuidv7'

/**
 * Mint a new entity id.
 *
 * UUIDv7, generated by the CALLER — including the browser, and later the Expo
 * app — not by the database. Two reasons, both structural:
 *
 *  1. Offline-first. A client with no connectivity must be able to create a
 *     shoot, a shot or a checklist item and sync it later. That is only
 *     possible if it can mint the id itself. It also makes creates idempotent:
 *     replaying a queued mutation hits `ON CONFLICT (id) DO NOTHING` instead of
 *     silently producing a duplicate.
 *
 *  2. v7 is time-ordered, so inserts land at the right-hand edge of the B-tree
 *     rather than scattering across it the way v4 does.
 *
 * Postgres 18's native `uuidv7()` is set as a column default for the
 * convenience of hand-written SQL, but application code must not depend on it
 * — doing so would re-couple us to a Postgres version and break (1).
 *
 * Lives in this package deliberately: `@pof/schemas` is browser- and
 * React-Native-safe (no Node builtins), so the same function runs on the
 * server, in the browser and in Metro.
 */
export function newId(): string {
  return uuidv7()
}
